C = dict(id='GL-40', title='Online Car Dealership Operations', group='Business and Commerce', level=4,
 summary='Run the online side of a car dealership honestly: list vehicles with true condition, price fairly, handle enquiries and test drives, check paperwork and keep buyers safe.',
 outcomes=['Explain how online car sales work and the legal duties of a seller.', 'Describe vehicles accurately with photos and checks.', 'Analyse price, margin and days in stock.', 'Create enquiry, viewing and handover processes.', 'Evaluate trust through reviews, returns and complaints.'],
 task='Prepare and run an online listing and enquiry process for 5 vehicles (real or practice) with condition reports, pricing, viewing checklist and paperwork checklist.',
 cond='Vehicle data and photos you may use, a listing page or spreadsheet, a checklist template, a mentor with motor-trade experience and a peer circle. About 10 weeks part-time.',
 std='Every listing states true condition, mileage, history and faults with evidence; price within a market range with reasons; ownership and paperwork verified; no pressure sales; complaints answered within 2 working days.',
 who='Dealership staff, small traders, online sales assistants, students.', req='None.',
 safety='Check ownership and finance status before listing. Never hide faults or wind back mileage. Follow consumer, safety and licensing rules for traders. Keep test drives safe and insured.',
 mods=[
 ('How online car sales work', 'Online adds reach, not shortcuts.', ['Listing, enquiry, viewing, test drive, paperwork, payment, handover.', 'Seller duties: accurate description; right to sell.', 'Buyer rights: returns, warranty as per local law.', 'Trust is the product.'], 'A listing that hides a repainted door loses trust and may break the law.', 'Map the sales steps.', 'Duties named at each step.'),
 ('Check the vehicle and paperwork', 'Know what you sell.', ['Ownership proof, registration, finance check.', 'History and service records.', 'Inspection checklist: body, tyres, lights, fluids, brakes, test drive.', 'Safety recalls.'], 'Mileage on the dash is 62,000 but service records show 78,000 earlier: investigate before listing.', 'Complete a checklist for two vehicles.', 'Findings recorded with photos.'),
 ('Honest descriptions and photos', 'Show what a buyer would see.', ['Title: make, model, year, mileage.', '20+ photos: all sides, interior, faults.', 'Plain condition notes.', 'Equipment list.'], 'Photos include a scratch on the rear bumper with a note.', 'Create three listings.', 'Every fault shown.'),
 ('Pricing', 'Fair and defendable.', ['Compare similar cars locally.', 'Adjust for mileage, condition, history.', 'Margin and costs: reconditioning, fees, finance.', 'Days in stock cost money.'], 'Cost 7,200 + prep 400; market 8,600; price 8,500; margin 900.', 'Price five vehicles.', 'Reasons for each price.'),
 ('Enquiries and trust', 'Fast, clear and respectful.', ['Reply within 2 hours in opening times.', 'Answer with facts and offer a video walk-around.', 'Avoid pressure; never take deposits without terms.', 'Keep a log.'], 'A buyer asks for rust photos: send underbody pictures and a mechanic\'s note.', 'Answer ten practice enquiries.', 'Replies factual and polite.'),
 ('Viewings and test drives', 'Safe for everyone.', ['ID, licence and insurance checks.', 'Route and speed rules.', 'Accompany the buyer.', 'Record condition before and after.'], 'The buyer\'s licence is checked and copied securely; the route avoids busy roads.', 'Write a test-drive procedure.', 'Procedure covers insurance.'),
 ('Contracts, payment and handover', 'Paperwork that protects both sides.', ['Sales agreement: price, condition, warranty, date.', 'Payment methods: traceable, no large cash.', 'Transfer of ownership and insurance.', 'Handover checklist and receipt.'], 'Payment by bank transfer confirmed before keys are released.', 'Make a paperwork checklist.', 'Checklist complete.'),
 ('After-sales and growth', 'Reputation lasts.', ['Follow-up call.', 'Handle faults under law and warranty.', 'Reviews and referrals.', 'Plan 90 days.'], 'A brake light fault in week 1 is fixed free and the buyer posts a good review.', 'Write after-sales rules and a plan.', 'Rules fair and clear.')],
 quiz=[('Name two seller duties.', 'Accurate description and right to sell.'), ('Why check finance status?', 'The car may be owned by a lender.'), ('Why show faults?', 'Honesty and legal duty.'), ('Pricing method?', 'Compare similar cars and adjust for condition.'), ('Why log enquiries?', 'To follow up and prove fair handling.'), ('Safe test-drive rule?', 'Check licence and insurance and accompany the buyer.'), ('Why avoid large cash?', 'Fraud and safety risk.'), ('What if mileage looks wrong?', 'Investigate before listing.'), ('Why after-sales?', 'Reputation and legal duties.'), ('What does handover include?', 'Receipt, ownership transfer and insurance.')],
 rubric=[('Honesty', 'Faults disclosed', 'Independent check attached'), ('Pricing', 'Reasons shown', 'Priced within days to sell'), ('Process', 'Enquiry and viewing steps', 'Replies under 2 hours'), ('Paperwork', 'Checklist complete', 'Zero errors'), ('After-sales', 'Rules fair', 'Complaints resolved quickly')],
 jobs=[('Online sales executive', 'Handles listings and enquiries'), ('Vehicle preparation coordinator', 'Checks and prepares cars'), ('Dealership admin', 'Handles paperwork'), ('Used-car trader', 'Runs a small business')],
 next='Virtual Interior Design Consulting; E-Commerce Growth Marketing; Marketplace Fulfilment Selling.',
 local='Trader licences, vehicle registration, warranty and consumer-return rules differ by place; check them first.',
 evidence='Your evidence: sales map, two inspection checklists, three listings, price sheet, enquiry log, test-drive procedure and paperwork checklist.',
 ladder=[('Basics of cars', 'Know the parts. Notes: walk-round.'), ('Awareness', 'Know seller duties. Notes: case studies.'), ('Foundation', 'List one car. Notes: honest.'), ('Practitioner', 'This course. Notes: five vehicles.'), ('Specialist', 'Finance and trade-ins. Notes: rules.'), ('Advanced', 'Lead a showroom. Notes: compliance.'), ('Super expert', 'Set method and teach teachers. Notes: ethics review.')])
